return [
  { json: { parentFolderId: '1-1EdTSWeoFPnbRa_hKdYsX4aMnqiQSSE', provider: 'gmail-only' } },
  { json: { parentFolderId: '1L5xu6tTaS6yZXbHpTrpE4IQ1xjV8G_J8', provider: 'outlook-only' } },
  { json: { parentFolderId: '102oeld1yMYGMmWs2Od198HqO1KeVhv_n', provider: 'combined' } },
];

// Only client folders (and, when Config.onlyClients is filled, only those whose folder name contains one of the names).
const cfg = $('Config').first().json;
const only = String(cfg.onlyClients || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
return $input.all().filter(i => i.json.mimeType === 'application/vnd.google-apps.folder')
  .filter(i => !only.length || only.some(n => String(i.json.name || '').toLowerCase().includes(n)));

// Exact match on the name 'conversation'; remembers which client folder (name) each sheet belongs to.
const folderName = {};
for (const f of $('Keep Folders Only').all()) folderName[f.json.id] = f.json.name;
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const name = (item.json.name || '').toString().trim().toLowerCase();
  if (name !== 'conversation' || !item.json.id || seen.has(item.json.id)) continue;
  seen.add(item.json.id);
  const parent = Array.isArray(item.json.parents) ? item.json.parents[0] : '';
  out.push({ json: { id: item.json.id, client: folderName[parent] || '(unknown client)' } });
}
// BATCHES: a run over all ~600 sheets at once can run out of memory and stop without an error. Config.startAt / maxSheets pick a slice of the
// (stable, sorted by sheet id) list: startAt 0 + maxSheets 40 = sheets 1-40, startAt 40 = sheets 41-80, and so on. maxSheets 0 = all sheets.
const cfg = $('Config').first().json;
out.sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
const total = out.length;
// When Config.onlyClients is filled the list is just those clients, so startAt / maxSheets are ignored.
const onlyNames = String(cfg.onlyClients || '').split(',').map(s => s.trim()).filter(Boolean);
const start = onlyNames.length ? 0 : Math.max(0, Number(cfg.startAt) || 0);
const max = onlyNames.length ? 0 : (Number(cfg.maxSheets) || 0);
const slice = max > 0 ? out.slice(start, start + max) : out.slice(start);
return slice.map(x => ({ json: { ...x.json, totalSheetsFound: total, batchFrom: start + 1, batchTo: start + slice.length } }));

const pick = $('Pick Exact Conversation Sheet Match').item.json;
const props = $json.sheets?.[0]?.properties;
if (!props?.title || props.sheetId === undefined) {
  return { json: { spreadsheetId: pick.id, client: pick.client, totalSheetsFound: pick.totalSheetsFound, batchFrom: pick.batchFrom, batchTo: pick.batchTo, error: 'Could not resolve tab name / sheetId' } };
}
return { json: { spreadsheetId: pick.id, client: pick.client, totalSheetsFound: pick.totalSheetsFound, batchFrom: pick.batchFrom, batchTo: pick.batchTo, tabName: props.title, tabSheetId: props.sheetId } };

// Cleanup plan for ONE conversation sheet.
// 1) Duplicates: rows with the same moment (epoch seconds), the same subject (re:/fw: ignored) and the same sender (fromEmail OR the older
//    senderEmail column; a row without a sender joins the only sender present). The row with the MOST attachment links is kept (the first one on a tie);
//    links that only a removed row has are copied into an empty link cell of the kept row.
//    A row is only removed when it is CERTAINLY a copy of the kept row: same moment + subject + sender (above) AND either the same message id, or
//    (the recipients overlap or one side has none) AND (the message texts are identical, or both have at least 20 letters/digits and one is the beginning of the other,
//    letters/digits only - Gmail and Outlook cut the quoted part at slightly different places). Everything else is NOT removed and is listed under
//    reviewGroups (rows that look alike but cannot be proven to be the same message).
// 2) Junk: '&#65279;' style codes and invisible characters are removed from the message text.
// 3) Sort: the whole sheet is sorted by the timestamp column (done by the 'Apply' step, not here).
const info = $('Extract Tab Info').item.json;
const base = { spreadsheetId: info.spreadsheetId, client: info.client, tabName: info.tabName, tabSheetId: info.tabSheetId, totalSheetsFound: info.totalSheetsFound, batchFrom: info.batchFrom, batchTo: info.batchTo };
const res = $input.item.json || {};
if (info.error) return { json: { ...base, changed: false, note: info.error } };
if (res.error) return { json: { ...base, changed: false, note: 'read error: ' + JSON.stringify(res.error).slice(0, 200) } };
const values = Array.isArray(res.values) ? res.values : [];
if (values.length < 2) return { json: { ...base, rows: Math.max(0, values.length - 1), changed: false, note: 'empty sheet' } };

const secs = (t) => { const d = new Date(String(t == null ? '' : t).trim()); return isNaN(d.getTime()) ? null : Math.floor(d.getTime() / 1000); };
const norm = (s) => String(s == null ? '' : s).toLowerCase().replace(/\s+/g, ' ').trim();
const subj = (s) => { let x = norm(s), prev; do { prev = x; x = x.replace(/^(re|fw|fwd|aw|wg|sv|vs|rv|tr)\s*:\s*/, '').trim(); } while (x !== prev); return x; };
const addr = (s) => { const m = String(s == null ? '' : s).match(/[\w.+'\-]+@[\w.\-]+\.[a-z]{2,}/i); return m ? m[0].toLowerCase() : ''; };
const txt = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
const addrs = (s) => (String(s == null ? '' : s).toLowerCase().match(/[\w.+'\-]+@[\w.\-]+\.[a-z]{2,}/g) || []);
const colLetter = (i) => { let s = ''; i++; while (i > 0) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; };
const JUNK1 = /&#(65279|8203|8204|8205|847);?|&zwnj;|&nbsp;/gi;
const JUNK2 = /[​-‏⁠﻿͏]/g;

const H = values[0].map(h => String(h == null ? '' : h).trim());
const iTs = H.indexOf('timestamp'), iSub = H.indexOf('subject'), iFrom = H.indexOf('fromEmail'), iSend = H.indexOf('senderEmail'), iMsg = H.indexOf('message'), iId = H.indexOf('id'), iTo = H.indexOf('toEmail'), iRecv = H.indexOf('receiverEmails');
const linkCols = []; H.forEach((h, i) => { if (/^(attachment|webViewLink)\d+$/i.test(h)) linkCols.push(i); });
if (iTs < 0) return { json: { ...base, rows: values.length - 1, changed: false, note: 'no timestamp column' } };

const rows = [];
for (let k = 1; k < values.length; k++) {
  const r = values[k] || [];
  const links = linkCols.map(c => String(r[c] == null ? '' : r[c]).trim()).filter(Boolean);
  rows.push({ row: k + 1, r, secs: secs(r[iTs]), subject: subj(iSub >= 0 ? r[iSub] : ''), sender: addr(iFrom >= 0 ? r[iFrom] : '') || addr(iSend >= 0 ? r[iSend] : ''), text: txt(iMsg >= 0 ? r[iMsg] : ''), mid: String(iId >= 0 && r[iId] != null ? r[iId] : '').trim(), to: new Set([...addrs(iTo >= 0 ? r[iTo] : ''), ...addrs(iRecv >= 0 ? r[iRecv] : '')]), links });
}
const bySecSubj = new Map();
for (const x of rows) { if (x.secs === null) continue; const key = x.secs + '|' + x.subject; if (!bySecSubj.has(key)) bySecSubj.set(key, []); bySecSubj.get(key).push(x); }

const deleteRows = [], updates = [], dupSamples = [], reviewGroups = [];
let dupGroups = 0, linksMerged = 0, linksNotMerged = 0, reviewRows = 0;
const removed = new Set();
for (const [key, grp] of bySecSubj) {
  if (grp.length < 2) continue;
  const senders = [...new Set(grp.map(x => x.sender).filter(Boolean))];
  const clusters = senders.length ? senders.map(s => grp.filter(x => x.sender === s || (!x.sender && senders.length === 1))) : [grp];
  for (const cl of clusters) {
    if (cl.length < 2) continue;
    const keep = cl.slice().sort((a, b) => (b.links.length - a.links.length) || (a.row - b.row))[0];
    const have = new Set(keep.links);
    const compat = (a, b) => {
      if (a.mid && b.mid && a.mid === b.mid) return true;
      const toOk = !a.to.size || !b.to.size || [...a.to].some(e => b.to.has(e));
      if (!toOk) return false;
      if (a.text.length >= 5 && a.text === b.text) return true;   // identical (short) texts: same moment + subject + sender + recipients + identical text
      if (a.text.length < 20 || b.text.length < 20) return false;
      return a.text.startsWith(b.text) || b.text.startsWith(a.text);
    };
    let removedHere = 0;
    for (const x of cl) {
      if (x === keep) continue;
      if (!compat(keep, x)) { reviewRows++; if (reviewGroups.length < 12) reviewGroups.push({ keptRow: keep.row, notRemovedRow: x.row, subject: key.split('|').slice(1).join('|').slice(0, 60), why: (!x.to.size || !keep.to.size || [...x.to].some(e => keep.to.has(e))) ? 'texts differ or too short' : 'different recipients' }); continue; }
      // links only this row has must fit into free link cells of the kept row; if they do not fit the row is NOT removed (nothing may be lost)
      const planned = [];
      let fits = true;
      for (const l of x.links) {
        if (have.has(l)) continue;
        const free = linkCols.find(c => !String(keep.r[c] == null ? '' : keep.r[c]).trim() && !updates.some(u => u.row === keep.row && u.col === c) && !planned.some(p => p.col === c));
        if (free === undefined) { fits = false; break; }
        planned.push({ col: free, value: l });
      }
      if (!fits) { linksNotMerged++; reviewRows++; if (reviewGroups.length < 12) reviewGroups.push({ keptRow: keep.row, notRemovedRow: x.row, subject: key.split('|').slice(1).join('|').slice(0, 60), why: 'its attachment link(s) would be lost (no free link column on the kept row)' }); continue; }
      removedHere++;
      deleteRows.push(x.row); removed.add(x.row);
      for (const p of planned) { updates.push({ row: keep.row, col: p.col, value: p.value, why: 'link from removed row ' + x.row }); have.add(p.value); linksMerged++; }
    }
    if (removedHere) dupGroups++;
    if (removedHere && dupSamples.length < 6) dupSamples.push({ kept: keep.row + ' (' + keep.links.length + ' links)', removed: cl.filter(x => x !== keep && removed.has(x.row)).map(x => x.row + ' (' + x.links.length + ' links)'), subject: key.split('|').slice(1).join('|').slice(0, 60) });
  }
}
let junkCells = 0; const junkSamples = [];
if (iMsg >= 0) {
  for (const x of rows) {
    if (removed.has(x.row)) continue;
    const m = x.r[iMsg];
    if (m == null || m === '') continue;
    const s = String(m);
    if (!(JUNK1.test(s) || JUNK2.test(s))) { JUNK1.lastIndex = 0; JUNK2.lastIndex = 0; continue; }
    JUNK1.lastIndex = 0; JUNK2.lastIndex = 0;
    const c = s.replace(JUNK1, ' ').replace(JUNK2, ' ').replace(/\s+/g, ' ').trim();
    if (c !== s) { updates.push({ row: x.row, col: iMsg, value: c, why: 'junk' }); junkCells++; if (junkSamples.length < 4) junkSamples.push(x.row + ': ' + s.slice(0, 50) + ' -> ' + c.slice(0, 50)); }
  }
}
deleteRows.sort((a, b) => a - b);
return { json: {
  ...base,
  rows: rows.length,
  changed: deleteRows.length > 0 || updates.length > 0,
  duplicateGroups: dupGroups,
  rowsToDelete: deleteRows.length,
  linksCopiedToKeptRows: linksMerged,
  rowsKeptBecauseLinksWouldBeLost: linksNotMerged,
  junkCellsToClean: junkCells,
  rowsLeftAloneForReview: reviewRows,
  timestampColumnIndex: iTs,
  dupSamples, junkSamples, reviewGroups,
  _deleteRows: deleteRows,
  _updates: updates.map(u => ({ range: colLetter(u.col) + u.row, value: u.value }))
} };

// Totals over all sheets looked at in this run (works for the dry run and for the real run).
const all = $input.all().map(i => i.json);
const f = all[0] || {};
const t = { dryRun: $('Config').first().json.dryRun !== false, sheetsInTotal: f.totalSheetsFound, thisBatch: f.batchFrom ? ('sheets ' + f.batchFrom + ' to ' + f.batchTo) : 'all', nextBatchStartAt: f.batchTo !== undefined && f.batchTo < f.totalSheetsFound ? f.batchTo : 'none - this was the last batch', sheetsLookedAt: all.length, sheetsWithChanges: 0, rowsRead: 0, rowsToDelete: 0, duplicateGroups: 0, junkCellsToClean: 0, linksCopiedToKeptRows: 0, rowsKeptBecauseLinksWouldBeLost: 0, rowsLeftAloneForReview: 0 };
const notes = [], withChanges = [];
for (const x of all) {
  t.rowsRead += x.rows || 0; t.rowsToDelete += x.rowsToDelete || 0; t.duplicateGroups += x.duplicateGroups || 0; t.junkCellsToClean += x.junkCellsToClean || 0;
  t.linksCopiedToKeptRows += x.linksCopiedToKeptRows || 0; t.rowsKeptBecauseLinksWouldBeLost += x.rowsKeptBecauseLinksWouldBeLost || 0; t.rowsLeftAloneForReview += x.rowsLeftAloneForReview || 0;
  if (x.changed || (x.rowsLeftAloneForReview || 0) > 0) { if (x.changed) t.sheetsWithChanges++; withChanges.push({ client: x.client, sheet: 'https://docs.google.com/spreadsheets/d/' + x.spreadsheetId, rows: x.rows, delete: x.rowsToDelete, junk: x.junkCellsToClean, copiedLinks: x.linksCopiedToKeptRows, review: x.rowsLeftAloneForReview, dupSamples: x.dupSamples, junkSamples: x.junkSamples, reviewGroups: x.reviewGroups }); }
  if (x.note) notes.push({ client: x.client, sheet: x.spreadsheetId, note: x.note });
}
// Biggest cleanups first (the old order hid the sheets with most deletions), plus a compact line for EVERY sheet that loses 25% or more of its rows.
const share = all.filter(x => (x.rowsToDelete || 0) > 0 && (x.rows || 0) > 0 && x.rowsToDelete / x.rows >= 0.25).map(x => ({ client: x.client, sheet: 'https://docs.google.com/spreadsheets/d/' + x.spreadsheetId, rows: x.rows, delete: x.rowsToDelete, percent: Math.round(100 * x.rowsToDelete / x.rows) })).sort((p, q) => q.percent - p.percent);
withChanges.sort((p, q) => (q.delete || 0) - (p.delete || 0));
return [{ json: { ...t, notes, sheetsLosingMoreThan25Percent: share, sheets: withChanges.slice(0, 40), moreSheetsNotShown: Math.max(0, withChanges.length - 40) } }];

// Sheets API requests per sheet, in this order: (1) set cells (link copies, junk cleanup) with the ORIGINAL row numbers, (2) delete the duplicate rows
// bottom-up, (3) sort by timestamp (if Config.sortToo).
const cfg = $('Config').first().json;
const out = [];
for (const it of $input.all()) {
  const s = it.json;
  const sid = s.spreadsheetId;
  const q = "'" + String(s.tabName).replace(/'/g, "''") + "'";
  const upd = s._updates || [];
  for (let i = 0; i < upd.length; i += 400) {
    out.push({ json: { kind: 'update', sid, label: s.client + ': set cells', body: { valueInputOption: 'RAW', data: upd.slice(i, i + 400).map(u => ({ range: q + '!' + u.range, values: [[u.value]] })) } } });
  }
  const rows = (s._deleteRows || []).slice().sort((a, b) => b - a);
  const ranges = [];
  for (const r of rows) { const last = ranges[ranges.length - 1]; if (last && last.start === r + 1) last.start = r; else ranges.push({ start: r, end: r }); }
  for (let i = 0; i < ranges.length; i += 300) {
    out.push({ json: { kind: 'delete', sid, label: s.client + ': delete rows', body: { requests: ranges.slice(i, i + 300).map(g => ({ deleteDimension: { range: { sheetId: s.tabSheetId, dimension: 'ROWS', startIndex: g.start - 1, endIndex: g.end } } })) } } });
  }
  if (cfg.sortToo !== false && s.timestampColumnIndex !== undefined) {
    out.push({ json: { kind: 'sort', sid, label: s.client + ': sort', body: { requests: [{ sortRange: { range: { sheetId: s.tabSheetId, startRowIndex: 1, startColumnIndex: 0 }, sortSpecs: [{ dimensionIndex: s.timestampColumnIndex, sortOrder: 'ASCENDING' }] } }] } } });
  }
}
return out;

const all = $input.all().map(i => i.json);
const failed = all.filter(x => x.error).length;
return [{ json: { requestsSent: all.length, requestsFailed: failed, note: failed ? 'Some requests failed: open the Apply node output and check the error items; run again for those clients (onlyClients).' : 'All requests succeeded.' } }];
